# Check for vertical 0-neighbors rule: 0 becomes 8 if it has a 0-neighbor in same column (above or below)
def has_vertical_zero_neighbor(r, c, grid):
    return 0 <= r-1 < len(grid) and grid[r-1][c] == 0 or \
           0 <= r+1 < len(grid) and grid[r+1][c] == 0

print("Checking vertical 0-neighbor rule:")
def verify_rule():
    all_match = True
    for r in range(13):
        for c in range(13):
            has_v_neighbor = has_vertical_zero_neighbor(r, c, input_grid)
            expected_8 = has_v_neighbor
            actual_8 = output_grid[r][c] == 8
            if expected_8 != actual_8:
                print(f"MISMATCH at ({r},{c}): input{input_grid[r][c]}, has_v_neighbor={has_v_neighbor}, output_8={actual_8}, actual_8={actual_8}")
                all_match = False
    return all_match

