def transform(grid):
    """Returns a new grid where 0s with 0-neighbors become 8."""
    rows = len(grid)
    cols = len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                # Check for 0-neighbor (4-adjacency)
                found_neighbor = False
                neighbors = [[r-1, c], [r+1, c], [r, c-1], [r, c+1]]
                for nr, nc in neighbors:
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                        found_neighbor = True
                        break
                if found_neighbor:
                    result[r][c] = 8
    return result

